# ==================== NC ATTACKS ====================
async def ncemo_attack(chat_id, target, session_id):
    bi = 0
    while session_id in active_nc and active_nc.get(session_id, True):
        try:
            tasks = []
            for _ in range(BOTS_PER_BATCH):
                if bi >= len(bots): bi = 0
                L, R = random.choice(NC_BORDERS)
                word = random.choice(NC_WORDS)
                title = f"{L} {target} {word} {R}"[:255]
                tasks.append(fire_nc(bots[bi], chat_id, title))
                bi += 1
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(NC_SPEED)
        except:
            await asyncio.sleep(0.5)

