# ==================== GHOST DELETE HANDLER ====================
async def handle_ghost_delete(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """✅ Auto-delete ALL spam messages when ghost mode active - ONLY allow master & bots"""
    if not update.message or not update.message.chat_id or not update.message.from_user:
        return
    
    chat_id = str(update.message.chat_id)
    user_id = update.message.from_user.id
    
    # Check if ghost mode is active in this chat
    for session_id in list(active_ghost.keys()):
        if session_id.startswith(chat_id) and active_ghost.get(session_id, False):
            # ✅ ONLY ALLOW: Master ID + Bot messages
            # OTHERS (NORMAL USERS): DELETE IMMEDIATELY
            
            # Allow master
            if user_id == MASTER_ID:
                return
            
            # Allow sudo users
            if user_id in SUDO_USERS:
                return
            
            # Allow bots
            if update.message.from_user.is_bot:
                return
            
            # 🗑️ DELETE ALL OTHERS - Any spam/message from normal users
            try:
                await context.bot.delete_message(
                    chat_id=update.message.chat_id,
                    message_id=update.message.message_id
                )
            except:
                pass
            
            break

# ==================== GROUP MONITORING ====================
async def group_monitor(update: Update, context: ContextTypes.DEFAULT_TYPE):
    if not update.chat_member:
        return
    
    chat = update.chat_member.chat
    user = update.chat_member.new_chat_member.user
    old_status = update.chat_member.old_chat_member.status if update.chat_member.old_chat_member else None
    new_status = update.chat_member.new_chat_member.status
    by_user = update.chat_member.from_user
    
    if user.is_bot:
        return
    
    if user.id == MASTER_ID:
        return
    
    chat_info = f"""
👤 ꪊ𝘴ꫀʀ : {user.first_name} {user.last_name or ''}
🆔 ɪᴅ: {user.id}
🔗 ꪊ𝘴ꫀꪀꪖᴍꫀ : @{user.username or 'No username'}
📅 ᴛɪᴍꫀ : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}
💬 ᥴꫝꪖᴛ : {chat.title}
🆔 ᥴꫝꪖᴛɪᦔ : {chat.id}
"""
    
    try:
        if new_status == "member" and (old_status == "left" or old_status == "kicked" or old_status is None):
            await context.bot.send_message(
                MASTER_ID,
                f"🟢 𝙉𝙀𝙒 𝙈𝙀𝙈𝘽𝙀𝙍 𝙅𝙊𝙄𝙉𝙀𝘿\n{chat_info}"
            )
            try:
                await update.effective_chat.send_message(
                    f"👋 𝙒𝙀𝙇𝘾𝙊𝙈𝙀 - {user.mention_html()}! 🎉\n💬 {chat.title}"
                )
            except:
                pass
        
        elif new_status == "left" or new_status == "kicked":
            action = "𝙇𝙀𝙁𝙏" if new_status == "left" else "𝙆𝙄𝘾𝙆𝙀𝘿"
            await context.bot.send_message(
                MASTER_ID,
                f"🔴 {action}!\n{chat_info}"
            )
            
            if new_status == "kicked":
                try:
                    kick_message = f"""
❌ 𝙔𝙊𝙐 𝙒𝙀𝙍𝙀 𝙆𝙄𝘾𝙆𝙀𝘿!

👤 ᴍᴇ ᴋɪᴄᴋᴇᴅ ʙʏ: {by_user.mention_html() if by_user else 'Admin'}
📍 ᴛɢᴄ: {chat.title}
🆔 ᴄʜᴀᴛ ɪᴅ : {chat.id}
📅 ᴛɪᴍᴇ : {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}
"""
                    await context.bot.send_message(user.id, kick_message, parse_mode="HTML")
                except:
                    pass
                
                for bot in bots:
                    me = await bot.get_me()
                    if user.id == me.id:
                        await context.bot.send_message(
                            MASTER_ID,
                            f"⚠️ 𝘽𝙊𝙏 @{me.username} 𝙒𝘼𝙎 ??𝙄𝘾𝙆𝙀𝘿 𝙁𝙍𝙊𝙈 {chat.title}!\nCHAT ID: {chat.id}\nBy: {by_user.mention_html() if by_user else 'Admin'}"
                        )
        
        elif new_status == "administrator" and old_status != "administrator":
            await context.bot.send_message(
                MASTER_ID,
                f"🟡 𝙉𝙀𝙒 𝘼𝘿𝙈𝙄𝙉!\n{chat_info}"
            )
    except Exception as e:
        print(f"Monitor error: {e}")

# ==================== AI FUNCTIONS ====================
async def text_to_speech(text):
    url = f"https://translate.google.com/translate_tts?ie=UTF-8&q={text}&tl=hi&client=tw-ob"
    headers = {'User-Agent': 'Mozilla/5.0'}
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(url, headers=headers) as resp:
                if resp.status == 200:
                    return await resp.read()
    except:
        pass
    return None

async def generate_image(prompt):
    url = f"https://image.pollinations.ai/prompt/{prompt.replace(' ', '%20')}?width=512&height=512&seed={random.randint(1,999999)}&nologo=true"
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(url) as resp:
                if resp.status == 200:
                    return await resp.read()
    except:
        pass
    return None

async def generate_video_frames(prompt, frames=4):
    results = []
    for i in range(frames):
        url = f"https://image.pollinations.ai/prompt/{prompt.replace(' ', '%20')}%20animation%20frame%20{i}?width=512&height=512"
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(url) as resp:
                    if resp.status == 200:
                        results.append(await resp.read())
            await asyncio.sleep(0.3)
        except:
            pass
    return results if len(results) >= 2 else None

# ==================== SONG DOWNLOAD ====================
async def download_song(query):
    os.makedirs("downloads", exist_ok=True)
    
    ydl_opts = {
        'format': 'bestaudio/best',
        'postprocessors': [{
            'key': 'FFmpegExtractAudio',
            'preferredcodec': 'mp3',
            'preferredquality': '192',
        }],
        'outtmpl': 'downloads/%(title)s',
        'quiet': False,
        'no_warnings': False,
        'default_search': 'ytsearch',
        'socket_timeout': 30,
        'ignore_errors': True,
        'no_check_certificates': True,
        'verbose': False,
        'keep_fragments': False,
        'headers': {
            'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
            'Referer': 'https://www.youtube.com/',
            'Accept-Language': 'en-US,en;q=0.9'
        },
        'extractor_args': {
            'youtube': {
                'skip': ['dash', 'hls'],
            }
        },
        'youtube_include_dash_manifest': False,
        'youtube_include_hls_manifest': False,
    }
    
    try:
        loop = asyncio.get_event_loop()
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            info = await loop.run_in_executor(None, lambda: ydl.extract_info(query, download=True))
            
            if info:
                if 'entries' in info:
                    info = info['entries'][0]
                
                title = info.get('title', query)[:50]
                base_name = os.path.join('downloads', title.replace('/', '_').replace('\\', '_'))
                mp3_file = f"{base_name}.mp3"
                
                # Wait for mp3 file to be created
                for _ in range(30):
                    if os.path.exists(mp3_file):
                        return mp3_file, info.get('title', query)
                    await asyncio.sleep(0.3)
                
                # Check if file exists with any audio extension
                for ext in ['.mp3', '.m4a', '.wav', '.opus', '.vorbis']:
                    test_file = f"{base_name}{ext}"
                    if os.path.exists(test_file):
                        return test_file, info.get('title', query)
    except Exception as e:
        print(f"Download error: {str(e)[:100]}")
    
    return None, None

async def delayed_cleanup(path):
    await asyncio.sleep(5)
    try:
        os.remove(path)
    except:
        pass

