# ==================== CUSTOM SPAM ====================
EMOJI_LIST = ["🔥", "💀", "⚡", "💥", "🎯", "👻", "🌪️", "⚔️", "🗡️", "💎", "🏆", "🎪", "🎭", "🎨", "🎬", "🎤", "🎧", "🎸", "🎹", "🎺", "🎻", "🥁", "🎲", "🎳", "🎮", "🎯", "🎰", "🃏", "🀄", "🎴", "🌟", "⭐", "✨", "💫", "🌠", "🔮", "🧿", "💠", "🔷", "🔶", "🔹", "🔸", "🔺", "🔻", "💠", "🟫", "🟪", "🟨", "🟧", "🟥", "🟩", "🟦", "⬛", "⬜", "🟐", "💢", "💬", "💭", "🌪️", "⚡", "🌊", "🔥", "❄️", "☄️", "💨", "💧", "🌈", "☀️", "🌙", "⭐", "✨"]

async def custom_spam_loop(chat_id, text, session_id):
    bi = 0
    emoji_idx = 0
    while session_id in active_spam and active_spam.get(session_id, True):
        try:
            tasks = []
            for _ in range(BOTS_PER_BATCH):
                if bi >= len(bots): bi = 0
                emoji = EMOJI_LIST[emoji_idx % len(EMOJI_LIST)]
                msg = f"{emoji} {text} {emoji}"
                tasks.append(bots[bi].send_message(chat_id, msg))
                bi += 1
                emoji_idx += 1
            await asyncio.gather(*tasks, return_exceptions=True)
            await asyncio.sleep(SPAM_DELAY)
        except:
            await asyncio.sleep(0.5)

@only_sudo
async def spam(update, context):
    if not context.args:
        return await update.message.reply_text("⚠️ /spam <custom_text>")
    custom_text = " ".join(context.args)
    chat_id = update.message.chat_id
    sid = f"{chat_id}_spam_custom"
    if sid in active_spam: active_spam[sid] = False; await asyncio.sleep(0.1)
    active_spam[sid] = True
    asyncio.create_task(custom_spam_loop(chat_id, custom_text, sid))
    await update.message.delete()

