# ==================== SONG COMMAND ====================
@only_sudo
async def song(update, context):
    if not context.args:
        return await update.message.reply_text("🎵 /song <song name>")
    query = " ".join(context.args)
    msg = await update.message.reply_text(f"🎵 Dᴏᴡɴʟᴏᴀᴅɪɴɢ: {query}...")
    
    try:
        song_path, title = await download_song(query)
        if song_path and os.path.exists(song_path):
            try:
                with open(song_path, 'rb') as audio:
                    await update.message.reply_audio(
                        audio=audio, 
                        title=title[:50] if title else "Song", 
                        performer="🎵 GOJO AbbU V10"
                    )
                await msg.delete()
                asyncio.create_task(delayed_cleanup(song_path))
            except Exception as e:
                await msg.edit_text(f"❌ Upload Error: {str(e)[:50]}")
        else:
            await msg.edit_text("❌ Song not found! Try another query.")
    except Exception as e:
        await msg.edit_text(f"❌ Error: {str(e)[:50]}")

