# ==================== GHOST SPAM FILTER ====================
async def handle_ghost_spam_filter(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """🗑️ Delete spam and group change attempts during ghost mode"""
    if not update.message or not update.message.chat_id or not update.message.from_user:
        return
    
    chat_id = str(update.message.chat_id)
    user_id = update.message.from_user.id
    
    # Only delete if ghost is active
    for session_id in list(active_ghost.keys()):
        if session_id.startswith(chat_id) and active_ghost.get(session_id, False):
            # Exceptions - don't delete these users
            if user_id in [MASTER_ID] or user_id in SUDO_USERS or update.message.from_user.is_bot:
                return
            
            # Delete spam messages
            try:
                await context.bot.delete_message(
                    chat_id=update.message.chat_id,
                    message_id=update.message.message_id
                )
            except:
                pass
            break

# ==================== SWIPE AUTO-REPLY HANDLER ====================
async def handle_swipe_autoreply(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Auto-reply to any message when swipe is active in the group"""
    if not update.message or not update.message.chat_id or update.message.from_user.is_bot:
        return
    
    chat_id = str(update.message.chat_id)
    
    # Check all active swipe sessions for this chat
    for session_id in list(active_swipe.keys()):
        if session_id.startswith(chat_id) and active_swipe.get(session_id, False):
            try:
                # Extract level from session_id (format: chat_id_swipe1_user_id)
                parts = session_id.split('_')
                level = int(parts[2].replace('swipe', '')) - 1 if 'swipe' in session_id else 0
                
                if level < len(SWIPE_REPLIES):
                    reply = random.choice(SWIPE_REPLIES[level]).format("randi")
                    await update.message.reply_text(reply)
                    await asyncio.sleep(0.2)
            except:
                pass

