@only_sudo
async def yt(update, context):
    if not context.args:
        return await update.message.reply_text("▶️ /yt <YouTube_link_or_search>")
    
    query = " ".join(context.args)
    msg = await update.message.reply_text("⏳ Downloading...")
    
    try:
        ydl_opts = {'format': 'best', 'quiet': True, 'no_warnings': True, 'max_downloads': 1}
        with yt_dlp.YoutubeDL(ydl_opts) as ydl:
            info = ydl.extract_info(query, download=True)
            video_file = ydl.prepare_filename(info)
            
            with open(video_file, 'rb') as video:
                await update.message.reply_document(video, caption=f"🎥 {info.get('title', 'Video')}")
            
            os.remove(video_file)
        await msg.delete()
    except Exception as e:
        await msg.edit_text(f"❌ Failed!")

