@only_sudo
async def unmute(update, context):
    if not update.message.reply_to_message:
        return await update.message.reply_text("🔊 /unmute [reply to user]")
    
    user = update.message.reply_to_message.from_user
    try:
        await update.effective_chat.restrict_member(user.id, ChatPermissions(can_send_messages=True))
        await update.message.reply_text(f"🔊 {user.mention_html()} unmuted!", parse_mode='HTML')
    except:
        await update.message.reply_text("❌ Error!")

@only_sudo
async def lock(update, context):
    try:
        await update.effective_chat.set_permissions(ChatPermissions(can_send_messages=False))
        await update.message.reply_text("🔒 Chat locked!")
    except:
        await update.message.reply_text("❌ Error!")

@only_sudo
async def unlock(update, context):
    try:
        await update.effective_chat.set_permissions(ChatPermissions(can_send_messages=True))
        await update.message.reply_text("🔓 Chat unlocked!")
    except:
        await update.message.reply_text("❌ Error!")

