# ==================== MAIN ====================
async def main():
    global apps, bots
    
    print("\n" + "="*60)
    print(" 🔥 GOJO ᴠ10 ᴜʟᴛɪᴍᴀᴛᴇ 🔥 ")
    print(f" ɴᴄ: {NC_DELAY}s | sᴘᴀᴍ: {SPAM_DELAY}s | ʙᴀᴛᴄʜ: {BOTS_PER_BATCH}")
    print("="*60)
    
    for token in TOKENS:
        try:
            app = build_app(token)
            apps.append(app)
            bots.append(app.bot)
            await app.initialize()
            await app.start()
            await app.updater.start_polling()
            print(f"✅ {token[:15]}...")
        except Exception as e:
            print(f"❌ {str(e)[:50]}")
    
    print(f"\n🔥 {len(bots)} Bᴏᴛs Oɴʟɪɴᴇ - Rᴇᴀᴅʏ!")
    print("="*60 + "\n")
    
    await asyncio.Event().wait()

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("\n👾 sᴛᴏᴘᴘᴇᴅ!")